import express from 'express';
import { randomUUID } from 'node:crypto';

const app = express();
app.use(express.json());

const processed = new Map(); // Idempotency-Key -> stored response (production: Redis/DB with a TTL)
const payments = [];

app.post('/api/payments', (req, res) => {
  const key = req.get('Idempotency-Key');
  if (!key) return res.status(400).json({ error: 'Idempotency-Key header required' });
  if (!(req.body?.amount > 0)) return res.status(400).json({ error: 'positive amount required' });
  const previous = processed.get(key);
  if (previous) return res.status(previous.status).json(previous.body); // a retry: replay, don't charge again

  const payment = { id: randomUUID(), amount: req.body.amount, status: 'captured' };
  payments.push(payment); // the side effect happens once per key
  processed.set(key, { status: 201, body: payment });
  res.status(201).json(payment);
});

app.listen(3000);

