  if (await User.exists({ email: parsed.data.email })) { // also keep a unique index: parallel requests can both pass this check
    return res.status(409).json({ error: { code: 'EMAIL_TAKEN' } });
  }
  const user = await User.create(parsed.data);
  res.status(201).location(`/api/users/${user.id}`).json(user);
});

app.delete('/api/users/:id', requireAuth, async (req, res) => {
  if (req.user.role !== 'admin') return res.status(403).json({ error: { code: 'FORBIDDEN' } });
  const deleted = await User.findByIdAndDelete(req.params.id);
  if (!deleted) return res.status(404).json({ error: { code: 'NOT_FOUND' } });
  res.status(204).end();
});

