// Keyset (cursor) pagination over items sorted by createdAt DESC, id DESC
const encode = (item) => Buffer.from(JSON.stringify([item.createdAt, item.id])).toString('base64url');
const decode = (cursor) => JSON.parse(Buffer.from(cursor, 'base64url').toString());

function listPage(items, limit, cursor) {
  const sorted = [...items].sort((a, b) => b.createdAt - a.createdAt || b.id - a.id);
  let start = 0;
  if (cursor) {
    const [createdAt, id] = decode(cursor);
    // first item strictly after the cursor in sort order
    start = sorted.findIndex((x) => x.createdAt < createdAt || (x.createdAt === createdAt && x.id < id));
    if (start === -1) start = sorted.length;
  }
  const page = sorted.slice(start, start + limit);
  const hasMore = start + limit < sorted.length;
  return { items: page, nextCursor: hasMore ? encode(page[page.length - 1]) : null };
}
// SQL:     WHERE (created_at, id) < ($1, $2) ORDER BY created_at DESC, id DESC LIMIT $3
// MongoDB: { $or: [{ createdAt: { $lt: c } }, { createdAt: c, _id: { $lt: id } }] } + sort + limit

