// ---------- Session-based: the cookie holds only a random id ----------
const sessions = new Map(); // production: Redis with a TTL

function startSession(res, user) {
  const sid = randomBytes(32).toString('base64url');
  sessions.set(sid, { userId: user.id, role: user.role, expires: Date.now() + 60 * 60 * 1000 });
  res.cookie('sid', sid, { httpOnly: true, secure: true, sameSite: 'lax' });
}
function sessionAuth(req, res, next) {
  const session = sessions.get(req.cookies.sid); // one store lookup per request (req.cookies comes from cookie-parser)
  if (!session || session.expires < Date.now()) return res.status(401).end();
  req.user = { id: session.userId, role: session.role };
  next();
}
const endSession = (req) => sessions.delete(req.cookies.sid); // revoked instantly

// ---------- JWT-based: the token carries signed claims ----------
const SECRET = process.env.JWT_SECRET;
const issueToken = (user) => jwt.sign({ sub: String(user.id), role: user.role }, SECRET, { expiresIn: '15m' });
function jwtAuth(req, res, next) {
  try {
    const claims = jwt.verify(req.cookies.token, SECRET, { algorithms: ['HS256'] }); // no lookup
    req.user = { id: claims.sub, role: claims.role };
    next();
  } catch {
    res.status(401).end(); // missing, tampered or expired
  }
}
// "Logout" can only clear the cookie: a copied token works until exp (at most 15 minutes)

