import { randomBytes, createHash, timingSafeEqual } from 'node:crypto';

// Client: a secret verifier; only its SHA-256 hash is sent in the redirect
function createPkcePair() {
  const codeVerifier = randomBytes(32).toString('base64url'); // 43 chars
  const codeChallenge = createHash('sha256').update(codeVerifier).digest('base64url');
  return { codeVerifier, codeChallenge };
}

// Authorization server, at POST /token: does the verifier match the stored challenge?
function verifyPkce(codeVerifier, storedChallenge) {
  const computed = Buffer.from(createHash('sha256').update(codeVerifier).digest('base64url'));
  const expected = Buffer.from(storedChallenge);
  return computed.length === expected.length && timingSafeEqual(computed, expected);
}

const { codeVerifier, codeChallenge } = createPkcePair();
