import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;

class Pkce {
    private static final Base64.Encoder B64URL = Base64.getUrlEncoder().withoutPadding();

    static String newVerifier() {
        byte[] bytes = new byte[32];
        new SecureRandom().nextBytes(bytes);
        return B64URL.encodeToString(bytes); // 43 chars
    }

    static String challenge(String verifier) throws Exception {
        byte[] hash = MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII));
        return B64URL.encodeToString(hash);
    }

    static boolean verify(String verifier, String storedChallenge) throws Exception {
        return MessageDigest.isEqual( // constant-time comparison
            challenge(verifier).getBytes(StandardCharsets.US_ASCII),
            storedChallenge.getBytes(StandardCharsets.US_ASCII));
    }
}

