import express from 'express';

const app = express();
const clients = new Set(); // open SSE responses (demo: one channel; real code keys them by order id)

// SSE endpoint: one long-lived HTTP response per subscriber
app.get('/api/orders/:id/events', (req, res) => {
  res.set({ 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', Connection: 'keep-alive' });
  res.flushHeaders();
  res.write('retry: 3000\n\n'); // if the connection drops, the browser reconnects after 3 s
  clients.add(res);
  req.on('close', () => clients.delete(res)); // the client went away
});

// Called by the order service whenever the status changes
let eventId = 0;
function broadcast(status) {
  eventId += 1;
  const message = `id: ${eventId}\nevent: status\ndata: ${JSON.stringify({ status })}\n\n`;
  for (const res of clients) res.write(message);
}

app.listen(3000);
setTimeout(() => broadcast('PREPARING'), 1000);
setTimeout(() => broadcast('ON_THE_WAY'), 2000);

