// Layout thrashing: each offsetWidth read after a style write forces a synchronous layout
function widenAllSlow(boxes) {
  for (const box of boxes) {
    box.style.width = `${box.offsetWidth + 10}px`; // read (forces layout) then write, N times
  }
}

// Better: batch all reads, then all writes -> at most one layout
function widenAllFast(boxes) {
  const widths = Array.from(boxes, (box) => box.offsetWidth); // reads (works for arrays and NodeLists)
  boxes.forEach((box, i) => {
    box.style.width = `${widths[i] + 10}px`; // writes
  });
}

